import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · 综合复习与自测 · 第19–27课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第二册：实践与进步 · 综合复习与自测 · 第19–27课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-2/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第10–18课","link":"/life/english/new-concept/book-2/review-part-02"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第28–36课","link":"/life/english/new-concept/book-2/review-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第10–18课","link":"/life/english/new-concept/book-2/review-part-02"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第28–36课","link":"/life/english/new-concept/book-2/review-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-2/review-part-03.md","filePath":"life/english/new-concept/book-2/review-part-03.md"}'),n={name:"life/english/new-concept/book-2/review-part-03.md"};function i(r,e,l,h,p,d){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-综合复习与自测-·-第19–27课" tabindex="-1">第二册：实践与进步 · 综合复习与自测 · 第19–27课 <a class="header-anchor" href="#第二册-实践与进步-·-综合复习与自测-·-第19–27课" aria-label="Permalink to &quot;第二册：实践与进步 · 综合复习与自测 · 第19–27课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-19-·-情态动词的意义与形式" tabindex="-1">Lesson 19 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-19-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 19 · 情态动词的意义与形式 {#lesson-19-·-情态动词的意义与形式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Two seats may become available if someone cancels.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>选 cancel/cancels：if someone ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> cancels</p><p><strong>解析：</strong> 不定代词 someone 作主语时谓语按单数处理。</p></details><p><strong>表达迁移：</strong> 写一段购票经历，区分当时的可能性与最终买到的数量。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Two seats may become available if someone cancels. I left my phone number at the desk. An hour later, the clerk called with one spare ticket.</p><p>第一句的组织方式：may 修饰 become 表可能；if 从句 cancels 用现在时表达未来条件；someone 按单数处理。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：may to become 错误；情态动词后用原形，也不能把 may 解读成确定承诺。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-019">回看本课</a></p><h2 id="lesson-20-·-动名词与动词搭配" tabindex="-1">Lesson 20 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-20-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 20 · 动名词与动词搭配 {#lesson-20-·-动名词与动词搭配}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Ben enjoys fishing beside the old bridge.</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>填 fish 的形式：Ben enjoys ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> fishing</p><p><strong>解析：</strong> enjoy 通常接动名词作宾语。</p></details><p><strong>表达迁移：</strong> 介绍一项不以结果为唯一目标的爱好，使用 enjoy doing 和一个动名词主语。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Ben enjoys fishing beside the old bridge. He rarely catches anything. Listening to the water is enough for him.</p><p>第一句的组织方式：enjoys 是句子谓语，fishing 是作宾语的动名词，beside the old bridge 修饰 fishing 的地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：enjoy to fish 不是标准搭配；enjoy fishing 才表达喜欢钓鱼。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-020">回看本课</a></p><h2 id="lesson-21-·-被动语态与信息重点" tabindex="-1">Lesson 21 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-21-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 21 · 被动语态与信息重点 {#lesson-21-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Our sleep is disturbed by early flights.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>填 be：Our sleep ___ disturbed by early flights.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> sleep 在此为不可数名词，谓语用单数。</p></details><p><strong>表达迁移：</strong> 分析一个住处的优缺点，写清噪声、便利因素和自己的决定。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our sleep is disturbed by early flights. The rent is low, however. We have decided to stay until the end of the year.</p><p>第一句的组织方式：Our sleep 是承受影响的主语，is disturbed 是现在时被动，by early flights 表原因来源。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：noise 与 noisy 词性不同：traffic noise 是噪声，a noisy street 是吵闹的街道。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-021">回看本课</a></p><h2 id="lesson-22-·-动词、宾语与补足语" tabindex="-1">Lesson 22 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-22-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 22 · 动词、宾语与补足语 {#lesson-22-·-动词、宾语与补足语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A walker replied to the message inside the bottle.</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>填介词：She replied ___ my message.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> reply 搭配 to 引出回复对象。</p></details><p><strong>表达迁移：</strong> 写一段意外收到旧消息的经历，交代发现、回复和反应。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A walker replied to the message inside the bottle. He found it during a walk along the coast. The writer had almost forgotten sending it.</p><p>第一句的组织方式：replied 是谓语，to the message 是必要的介词补足部分；inside the bottle 修饰 message 的所在位置。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：reply the message 通常应改为 reply to the message；answer the message 则不加 to。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-022">回看本课</a></p><h2 id="lesson-23-·-被动语态与信息重点" tabindex="-1">Lesson 23 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-23-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 23 · 被动语态与信息重点 {#lesson-23-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A new footpath is being built behind our house.</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>补全进行时被动：The path is ___ built.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> being</p><p><strong>解析：</strong> 现在进行时被动结构为 is/are being done。</p></details><p><strong>表达迁移：</strong> 写一份三句工程进度说明，区分正在施工与预计完工。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A new footpath is being built behind our house. The builders expect to finish next month. Until then, we use the side gate.</p><p>第一句的组织方式：A new footpath 是主语，is being built 是现在进行时被动；behind our house 是地点，不是动作执行者。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：is building 表主动建造，不能让 footpath 像施工者一样行动；此处用 is being built。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-023">回看本课</a></p><h2 id="lesson-24-·-情态动词的意义与形式" tabindex="-1">Lesson 24 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-24-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 24 · 情态动词的意义与形式 {#lesson-24-·-情态动词的意义与形式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I lost my wallet, but someone returned it that evening.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>填 lose 的过去式：I ___ my wallet yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> lost</p><p><strong>解析：</strong> lose 的过去式为 lost。</p></details><p><strong>表达迁移：</strong> 写一个有损失但结果尚可的小故事，准确说明丢了什么、找回什么。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I lost my wallet, but someone returned it that evening. The cash was gone. My cards and keys were still inside.</p><p>第一句的组织方式：lost 与 returned 同为过去式推进事件；someone 是未知身份的人，it 指 wallet，but 标记转折。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：someone 作主语按单数处理；someone have 应改为 someone has。</p></details><p><a href="/life/english/new-concept/book-2/unit-01/lesson-024">回看本课</a></p><h2 id="lesson-25-·-间接引语与视角转换" tabindex="-1">Lesson 25 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-25-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 25 · 间接引语与视角转换 {#lesson-25-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I asked the driver where the bus stopped.</p><h3 id="练习-1-24" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-24" aria-label="Permalink to &quot;练习 1 {#练习-1-24}&quot;">​</a></h3><p>选语序：I asked where the bus stopped / where did the bus stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> where the bus stopped</p><p><strong>解析：</strong> 间接疑问句使用陈述语序。</p></details><p><strong>表达迁移：</strong> 转述一次问路过程，包含一个 where 间接问句和一次澄清。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I asked the driver where the bus stopped. He repeated the name of the street. Once he showed me the map, I understood.</p><p>第一句的组织方式：asked 带听者 the driver 和间接疑问从句；where 引导地点问题，从句不倒装。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：I asked where did it stop 错误；从句应为 where it stopped。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-025">回看本课</a></p><h2 id="lesson-26-·-一般现在时与习惯" tabindex="-1">Lesson 26 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-26-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 26 · 一般现在时与习惯 {#lesson-26-·-一般现在时与习惯}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My sister likes paintings with strong colours.</p><h3 id="练习-1-25" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-25" aria-label="Permalink to &quot;练习 1 {#练习-1-25}&quot;">​</a></h3><p>填 like：My sister ___ bright colours.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> likes</p><p><strong>解析：</strong> 一般现在时第三人称单数。</p></details><p><strong>表达迁移：</strong> 描述自己偏爱的艺术风格，再描述今天正在观看的一件不同作品。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My sister likes paintings with strong colours. Today she is studying a black-and-white drawing. She says its simple lines are beautiful.</p><p>第一句的组织方式：likes 表稳定偏好，paintings 是泛指复数，with strong colours 为后置修饰语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：She is liking this style 在一般偏好语境下不自然；常用 She likes this style。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-026">回看本课</a></p><h2 id="lesson-27-·-过去完成时与先后关系" tabindex="-1">Lesson 27 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-27-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 27 · 过去完成时与先后关系 {#lesson-27-·-过去完成时与先后关系}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We had covered the bags before the rain started.</p><h3 id="练习-1-26" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-26" aria-label="Permalink to &quot;练习 1 {#练习-1-26}&quot;">​</a></h3><p>填 cover：We had ___ the bags before it rained.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> covered</p><p><strong>解析：</strong> 过去完成时要求 had 加过去分词。</p></details><p><strong>表达迁移：</strong> 用四个事件描述露营遇雨，其中一件用过去完成时回顾。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We had covered the bags before the rain started. Water still entered through the tent door. We moved to a nearby shelter at dawn.</p><p>第一句的组织方式：had covered 标记较早动作，before 从句 started 给出过去参照点；bags 是受保护的物品。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：had went 错误；had 后用过去分词 gone，不能用过去式 went。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-027">回看本课</a></p>',76)])])}const m=s(n,[["render",i]]);export{g as __pageData,m as default};
